"""The corpus seam: where indexable documents come from.

A ``BaseCorpusSource`` yields the documents to index plus an opaque
``corpus_version`` identifying the snapshot. Any data source — the Mintlify docs
sites today, skills/tools/history later — implements this one interface, so
ingestion and indexing never depend on a specific source format.
"""

from abc import ABC, abstractmethod
from pathlib import Path
from typing import List, Tuple

from rasa.builder.document_retrieval.mintlify import MintlifySite, build_index
from rasa.builder.document_retrieval.source import SourceDocument


class BaseCorpusSource(ABC):
    """A source of documents to index, with a snapshot version."""

    @abstractmethod
    def load(self) -> Tuple[List[SourceDocument], str]:
        """Load the corpus.

        Returns:
            A tuple ``(documents, corpus_version)`` where ``corpus_version`` is an
            opaque string identifying this snapshot (e.g. a git commit). Used to
            stamp the index and drive incremental sync.
        """
        ...


class MintlifyCheckoutSource(BaseCorpusSource):
    """Yields documentation pages parsed from a local checkout of a Mintlify site.

    Parses the checkout's ``.mdx`` sources directly. The checkout's git commit is
    the corpus version.
    """

    def __init__(self, docs_root: str, site: MintlifySite) -> None:
        self._docs_root = docs_root
        self._site = site

    def load(self) -> Tuple[List[SourceDocument], str]:
        doc_index = build_index(_resolve_path(self._docs_root), self._site)
        documents = [page.to_source_document(self._site) for page in doc_index.pages]
        return documents, doc_index.docs_repo_commit


def _resolve_path(path: str) -> Path:
    return Path(path).expanduser().resolve()
